import { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { usePathname, useRouter } from 'src/routes/hooks';
import { paths } from 'src/routes/paths';
import { SplashScreen } from 'src/components/loading-screen';

import { RoleBasedGuard } from '.';

const signInPaths = { jwt: paths.auth.signIn };

export function AuthGuard({ children }) {
  const router = useRouter();
  const pathname = usePathname();

  const { loggedInTeacher } = useSelector((state) => state.AuthReducer);
  const [isChecking, setIsChecking] = useState(true);
  const [isCheckPermission] = useState(true);

  const createRedirectPath = (currentPath) => {
    const queryString = new URLSearchParams({ returnTo: pathname }).toString();
    return `${currentPath}?${queryString}`;
  };

  const check = () => {
    if (!loggedInTeacher) {
      const redirectPath = createRedirectPath(signInPaths.jwt);
      router.replace(redirectPath);
    } else {
      setIsChecking(false);
    }
  };

  useEffect(() => {
    check();
  }, [loggedInTeacher]);

  if (isChecking) {
    return <SplashScreen />;
  }

  if (!isCheckPermission) {
    return <RoleBasedGuard hasContent sx={{ py: 10 }} />;
  }

  return <>{children}</>;
}

import { useState, useEffect } from 'react';
import { useRouter, useSearchParams } from 'src/routes/hooks';
import { CONFIG } from 'src/global-config';
import { paths } from 'src/routes/paths';
import { SplashScreen } from 'src/components/loading-screen';
import { useSelector } from 'react-redux';

// ----------------------------------------------------------------------

export function GuestGuard({ children }) {
  const router = useRouter();

  const searchParams = useSearchParams();
  const returnTo = searchParams.get('returnTo') || CONFIG.auth.redirectPath;
  const { loggedInTeacher } = useSelector((state) => state.AuthReducer);

  const [isChecking, setIsChecking] = useState(true);
  const checkPermissions = async () => {
    if (loggedInTeacher) {
      if (returnTo === '/' || returnTo === '/dashboard') {
        router.replace(paths.dashboard.teacher.root);
      } else {
        router.replace(returnTo);
      }
      return;
    }
    setIsChecking(false);
  };

  useEffect(() => {
    checkPermissions();
  }, [loggedInTeacher]);

  if (isChecking) {
    return <SplashScreen />;
  }

  return <>{children}</>;
}

import { TextField } from '@mui/material';
import { useEffect, useState } from 'react';
import DatePicker from 'react-datepicker';
import 'react-datepicker/dist/react-datepicker.css';
import dateHelper from 'src/utils/dateHelper';

export default function DateRangePicker({
  showDateRangePicker,
  onDateChanges,
  minDate,
  maxDate,
  resetDuration,
  sDate,
  eDate,
}) {
  const [startDate, setStartDate] = useState(sDate);
  const [endDate, setEndDate] = useState(eDate);
  const [textValue, setTextValue] = useState('mm/dd/yyyy - mm/dd/yyyy');
  const [isDatePickerOpen, setIsDatePickerOpen] = useState(false);

  useEffect(() => {
    if (sDate || eDate) {
      setStartDate(sDate);
      setEndDate(eDate);
      if (sDate && eDate) {
        setTextValue(`${dateHelper.formatDate(sDate)} - ${dateHelper.formatDate(eDate)}`);
      }
    }
  }, [sDate, eDate]);

  useEffect(() => {
    if (showDateRangePicker && resetDuration) {
      setStartDate(null);
      setEndDate(null);
      setTextValue('mm/dd/yyyy - mm/dd/yyyy');
    }
    if (startDate === null && endDate === null) {
      setIsDatePickerOpen(true);
    }
  }, [showDateRangePicker, resetDuration]);

  const onDateChange = (dates) => {
    const [start, end] = dates;
    setStartDate(start);
    setEndDate(end);
    if (start && end) {
      setIsDatePickerOpen(false);
      setTextValue(`${dateHelper.formatDate(start)} - ${dateHelper.formatDate(end)}`);
      onDateChanges(start, end);
    }
  };

  if (!showDateRangePicker) return null;

  return (
    <DatePicker
      open={isDatePickerOpen}
      selected={startDate}
      onChange={onDateChange}
      startDate={startDate}
      endDate={endDate}
      minDate={minDate}
      maxDate={maxDate}
      dateFormat={'MM/dd/yyyy'}
      selectsRange
      showYearDropdown
      showMonthDropdown
      customInput={
        <TextField
          label="Between"
          variant="standard"
          value={textValue}
          sx={{ width: 200 }}
          InputProps={{
            onFocus: () => setIsDatePickerOpen(true),
          }}
        />
      }
    />
  );
}

import { useBoolean } from 'minimal-shared/hooks';
import { mergeClasses } from 'minimal-shared/utils';
import Collapse from '@mui/material/Collapse';
import { useTheme } from '@mui/material/styles';
import { useSelector } from 'react-redux';

import { Nav, NavUl, NavLi, NavSubheader } from '../components';
import { navSectionClasses, navSectionCssVars } from '../styles';

import { NavList } from './nav-list';

// ----------------------------------------------------------------------

export function NavSectionVertical({
  sx,
  data,
  render,
  className,
  slotProps,
  currentRole,
  enabledRootRedirect,
  cssVars: overridesVars,
  ...other
}) {
  const theme = useTheme();
  const { loggedInTeacher } = useSelector((state) => state.AuthReducer);
  const cssVars = { ...navSectionCssVars.vertical(theme), ...overridesVars };

  return (
    <Nav
      className={mergeClasses([navSectionClasses.vertical, className])}
      sx={[{ ...cssVars }, ...(Array.isArray(sx) ? sx : [sx])]}
      {...other}
    >
      <NavUl sx={{ flex: '1 1 auto', gap: 'var(--nav-item-gap)' }}>
        {data.map((group) => (
          <Group
            key={group.subheader ?? group.items[0].title}
            subheader={group.subheader}
            items={group.items}
            render={render}
            slotProps={slotProps}
            currentRole={currentRole}
            enabledRootRedirect={enabledRootRedirect}
            loggedInTeacher={loggedInTeacher}
          />
        ))}
      </NavUl>
    </Nav>
  );
}

// ----------------------------------------------------------------------

function Group({
  items,
  render,
  subheader,
  slotProps,
  currentRole,
  enabledRootRedirect,
}) {
  const groupOpen = useBoolean(true);

  const renderContent = () => (
    <NavUl sx={{ gap: 'var(--nav-item-gap)' }}>
      {items.map((list) => (
        <NavList
          key={list.title}
          data={list}
          render={render}
          depth={1}
          slotProps={slotProps}
          currentRole={currentRole}
          enabledRootRedirect={enabledRootRedirect}
        />
      ))}
    </NavUl>
  );

  return (
    <NavLi>
      {subheader ? (
        <>
          <NavSubheader
            data-title={subheader}
            open={groupOpen.value}
            onClick={groupOpen.onToggle}
            sx={slotProps?.subheader}
          >
            {subheader}
          </NavSubheader>

          <Collapse in={groupOpen.value}>{renderContent()}</Collapse>
        </>
      ) : (
        renderContent()
      )}
    </NavLi>
  );
}

import { isEqual } from 'es-toolkit';
import { useLocalStorage } from 'minimal-shared/hooks';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useSelector } from 'react-redux';

import { SETTINGS_STORAGE_KEY } from '../settings-config';

import { SettingsContext } from './settings-context';

// ----------------------------------------------------------------------

export function SettingsProvider({
  children,
  defaultSettings: baseSettings,
  storageKey = SETTINGS_STORAGE_KEY,
}) {
  const { tenantDetail } = useSelector((state) => state.AuthReducer);
  const mergedDefaultSettings = useMemo(() => {
    const tenantPrimary = tenantDetail?.primaryColor;
    const configPrimary = baseSettings?.primaryColor || 'preset3';

    return {
      ...(baseSettings || {}),
      primaryColor: tenantPrimary || configPrimary,
    };
  }, [baseSettings, tenantDetail?.primaryColor]);

  const { state, setState, resetState, setField } = useLocalStorage(
    storageKey,
    mergedDefaultSettings
  );

  useEffect(() => {
    if (tenantDetail?.primaryColor) {
      setField('primaryColor', tenantDetail.primaryColor);
    }
  }, [tenantDetail?.primaryColor]);

  const [openDrawer, setOpenDrawer] = useState(false);

  const onToggleDrawer = useCallback(() => {
    setOpenDrawer((prev) => !prev);
  }, []);

  const onCloseDrawer = useCallback(() => {
    setOpenDrawer(false);
  }, []);

  const canReset = !isEqual(state, mergedDefaultSettings);

  const onReset = useCallback(() => {
    resetState(mergedDefaultSettings);
  }, [mergedDefaultSettings, resetState]);

  const memoizedValue = useMemo(
    () => ({
      canReset,
      onReset,
      openDrawer,
      onCloseDrawer,
      onToggleDrawer,
      state,
      setState,
      setField,
    }),
    [canReset, onReset, openDrawer, onCloseDrawer, onToggleDrawer, state, setField, setState]
  );

  return <SettingsContext.Provider value={memoizedValue}>{children}</SettingsContext.Provider>;
}

import { zodResolver } from '@hookform/resolvers/zod';
import { LoadingButton } from '@mui/lab';
import {
  Autocomplete,
  Button,
  Checkbox,
  Chip,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Stack,
  TextField,
} from '@mui/material';
import { useEffect, useState } from 'react';
import { Controller, FormProvider, useForm } from 'react-hook-form';
import { useSelector } from 'react-redux';
import { z as zod } from 'zod';
import { Field } from 'src/components/hook-form';
import { toast } from 'src/components/snackbar';
import ApiService from 'src/services/ApiService';

const getClassSchema = (showHostel) =>
  zod.object({
    className: zod.string().trim().min(1, { message: 'Class Name is required.' }),
    annualFee: zod.coerce.number().positive({ message: 'Annual Fee is required.' }),
    hostelFee: showHostel
      ? zod.coerce.number().positive({ message: 'Hostel Fee is required.' })
      : zod.coerce.number().nullable().optional(),
    sections: zod.string().trim().optional(),
    subjectIds: zod.array(zod.number()).min(1, { message: 'Please select at least one subject.' }),
  });

const defaultValues = {
  className: '',
  annualFee: '',
  hostelFee: '',
  sections: '',
  subjectIds: [],
};

export function ClassDialog({ id, open, onClose, onSuccess }) {
  const tenant = useSelector((state) => state.AuthReducer.tenantDetail);
  const showHostel = Boolean(tenant && tenant.isHostel);
  const [isLoading, setIsLoading] = useState(false);
  const [isLoadingData, setIsLoadingData] = useState(false);
  const [subjects, setSubjects] = useState([]);

  const methods = useForm({
    resolver: zodResolver(getClassSchema(showHostel)),
    defaultValues,
  });

  const {
    reset,
    setError,
    handleSubmit,
    formState: { isSubmitting },
  } = methods;

  useEffect(() => {
    if (!open) return;
    loadSubjects();
    if (id) {
      loadClass();
    } else {
      reset(defaultValues);
    }
  }, [id, open]);

  const loadSubjects = async () => {
    const { data } = await ApiService.getSubjectAsync();
    if (data) {
      setSubjects(data);
    }
  };

  const loadClass = async () => {
    setIsLoadingData(true);
    try {
      const { data } = await ApiService.getClassDataByIdAsync(id);

      if (data) {
        reset({
          className: data.className,
          annualFee: data.annualFee,
          hostelFee: data.hostelFee != null ? data.hostelFee : '',
          sections: data.sections ? data.sections.join(', ') : '',
          subjectIds: data.subjectIds || [],
        });
      }
    } finally {
      setIsLoadingData(false);
    }
  };

  const onSubmit = handleSubmit(async (values) => {
    setIsLoading(true);

    const payload = {
      className: values.className,
      annualFee:
        values.annualFee === '' || values.annualFee == null ? null : Number(values.annualFee),
      hostelFee:
        values.hostelFee === '' || values.hostelFee == null ? null : Number(values.hostelFee),
      sections: values.sections
        .split(',')
        .map((x) => x.trim())
        .filter(Boolean),
      subjectIds: values.subjectIds,
      ...(id && { classId: Number(id) }),
    };
    const response = await ApiService.saveClassAsync(payload);

    if (response.data) {
      toast.success(id ? 'Class updated successfully.' : 'Class created successfully.');
      if (onSuccess) onSuccess();
      onClose();
      reset(defaultValues);
    } else if (response.errors) {
      response.errors.forEach((error) => {
        setError(error.param, {
          message: error.msg,
        });
      });
    }

    setIsLoading(false);
  });

  return (
    <Dialog open={open} onClose={onClose} fullWidth maxWidth="sm">
      <DialogTitle>{id ? 'Edit Class' : 'New Class'}</DialogTitle>

      {isLoadingData ? (
        <DialogContent
          sx={{
            display: 'flex',
            justifyContent: 'center',
            py: 5,
          }}
        >
          <CircularProgress />
        </DialogContent>
      ) : (
        <FormProvider {...methods}>
          <DialogContent>
            <Stack spacing={2} sx={{ mt: 1 }}>
              <Field.Text name="className" label="Class Name" fullWidth />

              <Field.Text name="annualFee" label="Annual Fee" type="number" fullWidth />

              {showHostel && (
                <Field.Text name="hostelFee" label="Hostel Fee" type="number" fullWidth />
              )}

              <Field.Text name="sections" label="Sections" placeholder="A, B, C" fullWidth />

              <Controller
                name="subjectIds"
                control={methods.control}
                render={({ field }) => (
                  <Autocomplete
                    {...field}
                    fullWidth
                    multiple
                    disableCloseOnSelect
                    options={subjects}
                    value={subjects.filter((subject) =>
                      (field.value || []).includes(subject.subjectId)
                    )}
                    getOptionLabel={(option) => option.subjectName}
                    isOptionEqualToValue={(option, value) => option.subjectId === value.subjectId}
                    onChange={(event, newValue) => {
                      field.onChange(newValue.map((item) => item.subjectId));
                    }}
                    renderInput={(params) => (
                      <TextField
                        {...params}
                        label="Subjects"
                        placeholder="Select Subjects"
                        error={!!methods.formState.errors.subjectIds}
                        helperText={
                          methods.formState.errors.subjectIds
                            ? methods.formState.errors.subjectIds.message
                            : ''
                        }
                      />
                    )}
                    renderOption={(props, option) => {
                      const isSelected = (field.value || []).includes(option.subjectId);

                      return (
                        <li {...props} key={option.subjectId}>
                          <Checkbox size="small" disableRipple checked={isSelected} />
                          {option.subjectName}
                        </li>
                      );
                    }}
                    renderTags={(selected, getTagProps) =>
                      selected.map((option, index) => (
                        <Chip
                          {...getTagProps({ index })}
                          key={option.subjectId}
                          label={option.subjectName}
                          size="small"
                          variant="soft"
                        />
                      ))
                    }
                  />
                )}
              />
            </Stack>
          </DialogContent>

          <DialogActions sx={{ justifyContent: 'flex-start' }}>
            <LoadingButton
              variant="contained"
              color="primary"
              loading={isSubmitting || isLoading}
              onClick={onSubmit}
            >
              Save
            </LoadingButton>
            <Button variant="outlined" color="error" onClick={onClose}>
              Cancel
            </Button>
          </DialogActions>
        </FormProvider>
      )}
    </Dialog>
  );
}

import { zodResolver } from '@hookform/resolvers/zod';
import { LoadingButton } from '@mui/lab';
import {
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Stack,
} from '@mui/material';
import { useState } from 'react';
import { FormProvider, useForm } from 'react-hook-form';
import { z as zod } from 'zod';
import { Field } from 'src/components/hook-form';
import { toast } from 'src/components/snackbar';
import ApiService from 'src/services/ApiService';

const SubjectSchema = zod.object({
  subjectName: zod.string().trim().min(1, { message: 'Subject Name is required.' }),
  subjectCode: zod.string().trim().min(1, { message: 'Subject Code is required.' }),
});

const defaultValues = {
  subjectName: '',
  subjectCode: '',
};

export function SubjectDialog({ id, open, onClose, onSuccess }) {
  const [isLoading, setIsLoading] = useState(false);

  const methods = useForm({
    resolver: zodResolver(SubjectSchema),
    defaultValues,
  });

  const {
    reset,
    setError,
    handleSubmit,
    formState: { isSubmitting },
  } = methods;

  const onSubmit = handleSubmit(async (values) => {
    setIsLoading(true);

    const payload = {
      subjectName: values.subjectName,
      subjectCode: values.subjectCode,
    };

    const response = await ApiService.saveSubjectAsync(payload);

    if (response.data) {
      toast.success(id ? 'Subject updated successfully.' : 'Subject created successfully.');
      if (onSuccess) onSuccess();
      onClose();
      reset(defaultValues);
    } else if (response.errors) {
      response.errors.forEach((error) => {
        setError(error.param, {
          message: error.msg,
        });
      });
    }

    setIsLoading(false);
  });

  return (
    <Dialog open={open} onClose={onClose} fullWidth maxWidth="sm">
      <DialogTitle>{id ? 'Edit Subject' : 'Add Subject'}</DialogTitle>

      {isLoadingData ? (
        <DialogContent
          sx={{
            display: 'flex',
            justifyContent: 'center',
            py: 5,
          }}
        >
          <CircularProgress />
        </DialogContent>
      ) : (
        <FormProvider {...methods}>
          <DialogContent>
            <Stack spacing={2} sx={{ mt: 1 }}>
              <Field.Text name="subjectName" label="Subject Name" fullWidth />

              <Field.Text name="subjectCode" label="Subject Code" fullWidth />
            </Stack>
          </DialogContent>

          <DialogActions sx={{ justifyContent: 'flex-start' }}>
            <LoadingButton
              variant="contained"
              color="primary"
              loading={isSubmitting || isLoading}
              onClick={onSubmit}
            >
              Save
            </LoadingButton>
            <Button variant="outlined" color="error" onClick={onClose}>
              Cancel
            </Button>
          </DialogActions>
        </FormProvider>
      )}
    </Dialog>
  );
}

import { CustomBreadcrumbs } from 'src/components/custom-breadcrumbs';
import { DashboardContent } from 'src/layouts/dashboard';
import { paths } from 'src/routes/paths';
import { TeacherSaveForm } from '../teacher-save-form';

export function ProfileEditView() {
  return (
    <DashboardContent>
      <CustomBreadcrumbs
        heading="Edit Profile"
        links={[{ name: 'Dashboard', href: paths.dashboard.root }, { name: 'Edit Profile' }]}
        sx={{ mb: { xs: 2, md: 2 } }}
      />
      <TeacherSaveForm />
    </DashboardContent>
  );
}
